  if (collection == null || typeof collection === 'number') {
    return [];
  }

  if (typeof collection === 'object' && !Array.isArray(collection)) {
    collection = Object.values(collection);
  }

  if (!Array.isArray(criteria)) {
    criteria = criteria == null ? [null] : [criteria];
