 * //   ]
 * // }
 */
export function groupBy<T, K extends string>(arr: readonly T[], getKeyFromItem: (item: T) => K): Record<K, T[]> {
  const result = {} as Record<K, T[]>;

  for (const item of arr) {
    const key = getKeyFromItem(item);

    if (result[key] == null) {
