  debounced.cancel = function () {
    if (timeoutId !== null) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }

    signal?.removeEventListener('abort', onAbort);
  };

  signal?.addEventListener('abort', onAbort);

  return debounced;
}

